/* ── THE FINISHES ──
   Moved out of the Stick Maker on 2026-09-04 for the reason the catalogue itself
   moved: two tools name these now. A finish is a word on a label and a word on a
   page, and the two cannot be allowed to differ — `White & Grey` is one product
   sold under one name, not `White` in one tool and `Whitegrey` in another.

   The comments below are the Stick Maker's own and are kept: they record why each
   entry exists and where its hex came from. */
window.COLOURS = [
    { id: 'white',       label: 'White',       hex: '#F7F7F7' },
    { id: 'purewhite',   label: 'Pure White',  hex: '#E8EEF2' },
    /* ── Added 2026-08-20, and it is a name rather than a shade ──
       The OSMO line is sold in Arctic White — the one finish in the range that is a product
       decision instead of a description of a photograph, which is why `docs/PRODUCT-MATRIX.md` §852
       records it by name and the matrix app has carried `aw` since it was written. The tool did
       not, so OSMO Pro and OSMO Max were being set as plain `White`: a different word on a label
       from the one on the box. The hex is the matrix app's own. */
    { id: 'arctic',      label: 'Arctic White', hex: '#F1F3F4' },
    /* Added 2026-08-14 on Akvantis's instruction. Placed third because the row runs light to
       dark and a grey belongs between the whites and the blue — the order is the only thing in
       this list a person navigates by. */
    { id: 'gray',        label: 'Gray',        hex: '#8A8F94' },
    { id: 'nightblue',   label: 'Night Blue',  hex: '#1B2A4A' },
    { id: 'slateblack',  label: 'Slate Black', hex: '#2E3338' },
    { id: 'black',       label: 'Black',       hex: '#111113' },
    /* ── Two surfaces, not two colours ──
       Chrome and brushed steel are both silver at a glance and a colour word cannot separate
       them, so they are named for the finish. Added when K5 was split in two and K1's three
       variants stopped fitting the palette: before this, chrome was being printed as `Gray`
       and steel as `White`, which is a wrong word on a label rather than an approximate one. */
    /* A1's second finish is one thing sold under one name — white housing, grey dials and
       base — so it is one entry and not two. The disc carries the body colour, which is what
       somebody matching a swatch to a box is looking at. */
    { id: 'whitegrey',   label: 'White & Grey', hex: '#E4E7E9' },
    { id: 'chrome',      label: 'Chrome',      hex: '#C9CED2' },
    { id: 'steel',       label: 'Brushed Steel', hex: '#9BA1A5' }
  ];


/* ⚠ MOVED HERE FROM THE STICK MAKER — 2026-09-04.
   The second generation was derived at runtime inside that tool, so the shared
   catalogue held 22 machines and the Stick Maker showed 26. The Digital Passport
   builder, reading the same file, was missing four models — and nothing said so,
   which is the kind of gap only found by somebody looking for a machine that exists.
   `DEVICES` below is `window.DEVICES`; the derivation is unchanged. */
/* ══════════════ THE SECOND GENERATION, BUILT FROM THE FIRST ══════════════
   `A1G2` is the same position in the range as `A1` and it wears the same mark: the matrix is
   explicit that the generation is **words on the carton and a code everywhere else** — the box
   reads `AKVANTIS A1 II`, while `A1G2` lives in the article, the plate and the serial. So the
   drawing is not duplicated here; the entries are derived from the first-generation ones and
   differ in exactly the three things that differ on the machine.

   ── What is different ──
   The finish is **Black only** — NextGen's own answer, against the first generation's Black
   and White & Grey. The serial code is `A1G2`, which is what a service call and a customs form
   quote. And the photograph is its own: `a1g2.png` and its three siblings are renders of the
   new machines, synced from the matrix app's `assets/products/next-gen/a/`. They are different
   units and they look it — putting the current housing on a G2 plate would be the one error on
   this sheet nobody could catch by reading it.

   `A2` has no second generation, and that is answered rather than missing: `docs/PRODUCT-MATRIX.md`
   §928, settled 2026-08-15 — *A2 is a current-line machine and has no NextGen counterpart; it
   ships today and the range that replaces it does not carry the position forward.* */
(function () {
  var G2 = { a1: 'A1G2', a3: 'A3G2', a5: 'A5G2', a7: 'A7G2' };
  /* ── Inserted after its predecessor, not appended to the end ──
     The picker reads `A1, A1 (G2), A2, A3, A3 (G2)…`, so a successor sits under the machine it
     succeeds and the eye compares the pair without hunting. Appended, the four G2 marks formed
     a second A-series at the bottom of the group — which reads as a range of nine rather than
     as five machines, four of which have a replacement. `A2` has no successor and simply has
     nothing under it, which is the shape of the fact. */
  Object.keys(G2).forEach(function (id) {
    var i = window.DEVICES.map(function (x) { return x.id; }).indexOf(id);
    var d = window.DEVICES[i];
    if (!d) return;
    window.DEVICES.splice(i + 1, 0, {
      id: id + 'g2', label: d.label, group: d.group, kind: d.kind,
      gen: '(G2)', code: G2[id],
      colours: ['black'],
      /* One render, and it serves the one finish — `null` is the key for a model that has a
         single picture, the same as A3 or K3 in the first generation. */
      imgs: { null: id + 'g2' },
      w: d.w, h: d.h, core: d.core, svg: d.svg
    });
  });
  /* ── The current line is not tagged, and that is the rule rather than an omission ──
     A machine shipping today is just `A1`: that is what is on its carton, in the shop and in
     the `Current` sheet, and a generation tag on it would be the tool inventing a designation
     nobody else uses. `G2` is a real code — it lives in the article, the plate and the serial
     — so it is the one that gets written down.

     The tag is therefore a mark of *succession*, not of position in a list. Read down the
     picker: an untagged mark is a machine you can order now, a tagged one is the range that
     replaces it. Tagging both ends would say the current line had been renamed, which it has
     not. */
})();
